def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {3: 0, 2: 0}
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in counts or (r, c) in seen:
                continue
            counts[color] += 1
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
    vals = [3] * counts[3] + [2] * counts[2]
    vals = (vals + [0] * 6)[:6]
    return [vals[:3], vals[3:]]
